/// <summary>
/// DCP - 08/09/2022 Code clean up of class METPrintMgmtDocTypeHelper and METPrintMgtDocTypeHandlerExt
/// Kurt Scerri - 03/03/2021
/// METPrintMgmtDocTypeHelper adds report design to print management
/// </summary>
public class METPrintMgtDocTypeHandler
{
}

Method.Source:
    /// <summary>
    /// MPJ_11539 - kscerri - 08/04/2021
    /// Adds report to the print mgmt new node
    /// </summary>
    /// <param name = "_docType">doctype</param>
    /// <param name = "_result">result</param>
    [SubscribesTo(classStr(PrintMgmtDocType), delegateStr(PrintMgmtDocType, getDefaultReportFormatDelegate))]
    public static void getDefaultReportFormatDelegate(PrintMgmtDocumentType _docType, EventHandlerResult _result)
    {
        switch(_docType)
        {
            case PrintMgmtDocumentType::METCustActivityStatement:
                _result.result(ssrsReportStr(METCustActivityStatement, Report));
                break;

            //MPJ_15231_Customer Statement DCP 29/03/2022
            case PrintMgmtDocumentType::METCustActivityStatementMulti:
                _result.result(ssrsReportStr(METCustActivityStatement, ReportMulti));
                break;

            case PrintMgmtDocumentType::PurchaseOrderInvoice:
                _result.result(ssrsReportStr(METVendInvoiceDocument, Report));
                break;

                      
            case PrintMgmtDocumentType::VendPaymAdvice:
                _result.result(ssrsReportStr(METBankPaymAdviceVendV2, Report));
                break;
                      
            case PrintMgmtDocumentType::CustCollectionLetter:
                _result.result(ssrsReportStr(METCustCollectionJour, Report));
                break;

            case PrintMgmtDocumentType::METArrivalOverviewDockCopy:
                _result.result(ssrsReportStr(METArrivalDockCopy, Report));
                break;

            //MPJ-34596 Start
            case PrintMgmtDocumentType::MetCoverNote:
                //Need to add default report once ready
                break;
            case PrintMgmtDocumentType::MetContinuousPermissionNotice:
                //Need to add default report once ready
                break;
            case PrintMgmtDocumentType::MetDangerousGoodsManifest:
                //Need to add default report once ready
                break;
            //MPJ-34596 End

            //CB123 SalesOrderExtractScreenforCSD -start
            case PrintMgmtDocumentType::InventPickList:
                _result.result(ssrsReportStr(METWMSPickingList_OrderPick, Report));
                break;
            //CB123 SalesOrderExtractScreenforCSD -end

            //CB175 Sales Confirmation - start
            case PrintMgmtDocumentType::SalesOrderConfirmation:
                METLegalEntityType metLegalEntitytype = CompanyInfo::find().METLegalEntityType;

                if (metLegalEntitytype == METLegalEntityType::Liquor)
                {
                    _result.result(ssrsReportStr(METSalesConfirm, ReportLiquor));
                }
                else if (metLegalEntitytype == METLegalEntityType::Food)
                {
                    _result.result(ssrsReportStr(METSalesConfirm, ReportFood));
                }
                break;
            //CB175 Sales Confirmation - end
        }
    }
